head.script:
scwin.createWindow = function() {};
scwin.doInit = function() {
    this.createWindow();
};
scwin.windowContainer1_onclickcustombtn = function(info) {
    if (info.btnIdx == 3) {
        windowContainer1.closeOthers(info.uniqueId);
    } else {
        alert(info.uniqueId);
        alert(info.btnId);
    }
};
scwin.trigger1_onclick = function(e) {
    var c_cnt = 4;
    var c_subName = "windowContainr_Fixed_WPF-1727_(WSQ-2853)_sub";
    var c_xmlName = ".xml";
    for (var i = 0; i < c_cnt; i++) {
        WebSquare.wUnit.getObjById('windowContainer1').createWindow(c_subName + i, null, 'windowContainr_Fixed_WPF-1727_(WSQ-2853)_sub.xml', "", null, "existWindow", null, null);
    }
};
scwin.trigger2_onclick = function(e) {
    WebSquare.wUnit.getObjById('windowContainer1').fixWindow($p.id+'windowContainer1_subWindow2');
};
scwin.trigger3_onclick = function(e) {
    WebSquare.wUnit.getObjById('windowContainer1').unfixWindow($p.id+'windowContainer1_subWindow2');
};
scwin.trigger4_onclick = function(e) {
    WebSquare.wUnit.getObjById('windowContainer1').createWindow('windowContainr_Fixed_WPF-1727_(WSQ-2853)_sub5', null, 'windowContainr_Fixed_WPF-1727_(WSQ-2853)_sub.xml', "", null, "newWindow", null, null, {
        fixed: true
    });
};
scwin.trigger5_onclick = function(e) {
    windowContainer1.createWindow({
        title: 'sub5',
        src: 'windowContainr_Fixed_WPF-1727_(WSQ-2853)_sub.xml',
        openAction: 'newWindow',
        fixed: true
    });
};
scwin.isFixed = function(id) {
    return WebSquare.wUnit.getJq(WebSquare.wUnit.getObjById(id).children[0]).hasClass("w2windowContainer_nameLayer_fixOn")
}
scwin.checktype1 = function() {
    return typeof WebSquare.wUnit.getObjById('windowContainer1_subWindow0');
}
scwin.checktype2 = function() {
    return typeof WebSquare.wUnit.getObjById('windowContainer1_subWindow1');
}
scwin.checktype3 = function() {
    return typeof WebSquare.wUnit.getObjById('windowContainer1_subWindow2');
}
scwin.checktype4 = function() {
    return typeof WebSquare.wUnit.getObjById('windowContainer1_subWindow3');
}
scwin.checktype5 = function() {
    return typeof WebSquare.wUnit.getObjById('windowContainer1_subWindow4');
}
scwin.checktype6 = function() {
    return typeof WebSquare.wUnit.getObjById('windowContainer1_subWindow5');
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 1. 브라우저에서 창 생성(init) 버튼을 클릭한다.
    //1. In your browser, click the Generate (init) button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('trigger1').click()");
    // verify step 1. 0 부터 3까지 4개의 windowContainer 가 생성된다.
    //1. Four windowContainers are created from 0 to 3.
    WebSquare.wUnit.addCommand("assert", "scwin.checktype1()", "object");
    WebSquare.wUnit.addCommand("assert", "scwin.checktype2()", "object");
    WebSquare.wUnit.addCommand("assert", "scwin.checktype3()", "object");
    WebSquare.wUnit.addCommand("assert", "scwin.checktype4()", "object");
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 2. 'sub2고정' 버튼을 클릭한다.
    //2. Click the 'sub2 pin' button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('trigger2').click()");
    // verify step 2. windowContainer sub2 가 고정된다.
    //2. windowContainer sub2 is fixed.
    WebSquare.wUnit.addCommand("assert", "scwin.isFixed('windowContainer1_nameLayer_'+$p.id+'windowContainer1_subWindow2')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 3. 'sub2고정해제' 버튼을 클릭한다.
    //3. Click the 'Unfreeze sub2' button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('trigger3').click()");
    // verify step 3. windowContainer sub2 가 고정해제된다.
    //3. windowContainer sub2 is unpinned.
    WebSquare.wUnit.addCommand("assert", "scwin.isFixed('windowContainer1_nameLayer_'+$p.id+'windowContainer1_subWindow2')", "false");
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 4. '고정 sub5 생성 (parameter type)' 버튼을 클릭한다.
    //4. Click the 'Create a fixed sub5 (parameter type)' button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('trigger4').click()");
    // verify step 4. 정상적으로 windowContainer sub5 가 createWindow 된다.
    //4. The windowContainer sub5 is normally createdWindow.
    WebSquare.wUnit.addCommand("assert", "scwin.checktype5()", "object");
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 5. '고정 sub5 생성 (json type)' 버튼을 클릭한다.
    //5. Click the 'Create a fixed sub5 (json type)' button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('trigger5').click()");
    // verify step 5. 정상적으로 windowContainer sub5 가 createWindow 된다.
    //5. The windowContainer sub5 is normally createdWindow.
    WebSquare.wUnit.addCommand("assert", "scwin.checktype6()", "object");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.doInit();
    //Function unitTest
    //Created By: Sang.do
    //Created By: 25-Jan-2018
    //end unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
